const LOCAL_TEST_HOSTS = new Set(["127.0.0.1", "localhost"]); const JSON_ENDPOINT_MATCHERS = ["formsubmit.co/ajax/"]; const LEAD_STORAGE_KEY = "rcc_pending_lead"; const ATTRIBUTION_STORAGE_KEY = "rcc_attribution"; const SESSION_ID_STORAGE_KEY = "rcc_session_id"; const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/i; function showFormStatus(form, message, type = "info") { let status = form.querySelector("[data-form-status]"); if (!status) { status = document.createElement("p"); status.className = `form-status form-status-${type}`; status.setAttribute("data-form-status", ""); status.setAttribute("role", "status"); status.setAttribute("aria-live", "polite"); form.append(status); } status.className = `form-status form-status-${type}`; status.textContent = message; } function safeSessionStorage(method, ...args) { try { return window.sessionStorage?.[method](...args); } catch { return null; } } function normaliseValue(value) { return typeof value === "string" ? value.trim() : ""; } function looksLikeEmail(value) { return EMAIL_PATTERN.test(normaliseValue(value)); } function looksLikePhone(value) { const digits = normaliseValue(value).replace(/\D/g, ""); return digits.length >= 8; } function getOrCreateSessionId() { const existing = safeSessionStorage("getItem", SESSION_ID_STORAGE_KEY); if (existing) { return existing; } const created = `rcc-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`; safeSessionStorage("setItem", SESSION_ID_STORAGE_KEY, created); return created; } function getStoredAttribution() { const raw = safeSessionStorage("getItem", ATTRIBUTION_STORAGE_KEY); if (!raw) { return {}; } try { return JSON.parse(raw); } catch { return {}; } } function rememberAttribution() { const params = new URLSearchParams(window.location.search); const stored = getStoredAttribution(); const current = { utm_source: normaliseValue(params.get("utm_source")), utm_medium: normaliseValue(params.get("utm_medium")), utm_campaign: normaliseValue(params.get("utm_campaign")) }; const merged = { utm_source: current.utm_source || stored.utm_source || "", utm_medium: current.utm_medium || stored.utm_medium || "", utm_campaign: current.utm_campaign || stored.utm_campaign || "" }; safeSessionStorage("setItem", ATTRIBUTION_STORAGE_KEY, JSON.stringify(merged)); getOrCreateSessionId(); return merged; } function buildLeadFieldMap(form) { const values = {}; const formData = new FormData(form); formData.delete("_honey"); formData.delete("botcheck"); for (const [key, value] of formData.entries()) { if (!(key in values)) { values[key] = normaliseValue(value); } } return values; } function inferPlanStatus(values) { const combined = [ values.plan_status, values.plan_managed, values.ndis_plan, values.service_type, values.form_type ] .filter(Boolean) .join(" ") .toLowerCase(); return /\b(ndis|plan-managed|plan managed|self-managed|self managed|plan manager)\b/.test(combined) ? "yes" : "no"; } function inferEmail(values) { const candidates = [values.email, values.contact_details]; return candidates.find((value) => looksLikeEmail(value)) || ""; } function inferPhone(values) { const candidates = [values.phone, values.contact_details]; return candidates.find((value) => looksLikePhone(value)) || ""; } function inferBookingWithin7Days(values) { const dateKeys = ["preferred_date", "date", "appointment_date", "booking_date", "session_date"]; const now = Date.now(); const sevenDays = 7 * 24 * 60 * 60 * 1000; for (const key of dateKeys) { const raw = normaliseValue(values[key]); if (!raw) { continue; } const parsed = Date.parse(raw); if (Number.isNaN(parsed)) { continue; } if (parsed >= now && parsed - now <= sevenDays) { return true; } } return false; } function storeLeadSuccessPayload(form) { const values = buildLeadFieldMap(form); const attribution = rememberAttribution(); const email = inferEmail(values); const phone = inferPhone(values); const message = normaliseValue(values.message); const formType = normaliseValue(values.form_type).toLowerCase(); const leadType = formType.includes("booking") ? "booking_request" : "enquiry"; const payload = { lead_type: leadType, plan_status: inferPlanStatus(values), phone_present: Boolean(phone), email_valid: looksLikeEmail(email), message_len: message.length, booking_within_7days: inferBookingWithin7Days(values), source: attribution.utm_source || "", medium: attribution.utm_medium || "", campaign: attribution.utm_campaign || "", session_id: getOrCreateSessionId(), ts: Date.now() }; safeSessionStorage("setItem", LEAD_STORAGE_KEY, JSON.stringify(payload)); } function getEndpoint(form) { const action = form.getAttribute("action") || ""; if (action.startsWith("/forms/")) { return action; } if (LOCAL_TEST_HOSTS.has(window.location.hostname)) { return "/__form_test__"; } const configuredKey = form.dataset.formEndpoint; const configured = configuredKey ? window.RCC_CONFIG?.[configuredKey] : window.RCC_CONFIG?.formEndpoint; return configured || action; } function shouldSubmitAsJson(endpoint) { return JSON_ENDPOINT_MATCHERS.some((matcher) => endpoint.includes(matcher)); } function shouldUseNativeSubmit(endpoint, form) { const endpointUrl = new URL(endpoint, window.location.href); return ( form?.hasAttribute("data-native-submit") || (endpointUrl.origin === window.location.origin && endpointUrl.pathname.startsWith("/forms/")) ); } function canEnhanceForms() { return ( typeof window.fetch === "function" && typeof window.FormData === "function" && typeof window.URLSearchParams === "function" ); } function buildJsonPayload(form) { const payload = {}; const formData = new FormData(form); formData.delete("_honey"); for (const [key, value] of formData.entries()) { payload[key] = typeof value === "string" ? value.trim() : value; } return JSON.stringify(payload); } async function assertSuccessfulJsonResponse(response) { if (!response.ok) { throw new Error(`Form request failed with status ${response.status}`); } const contentType = response.headers.get("content-type") || ""; if (!contentType.includes("application/json")) { return; } const payload = await response.clone().json(); if (payload.success === false || payload.success === "false") { throw new Error(payload.message || "Form provider returned an error"); } } async function handleFormSubmit(event) { if (!canEnhanceForms()) { return; } const form = event.currentTarget; const endpoint = getEndpoint(form); if (shouldUseNativeSubmit(endpoint, form)) { return; } event.preventDefault(); const submitButton = form.querySelector('button[type="submit"]'); const isLocalTest = LOCAL_TEST_HOSTS.has(window.location.hostname); const submitAsJson = shouldSubmitAsJson(endpoint); if (!endpoint || endpoint.includes("YOUR_")) { showFormStatus( form, "This form is not available right now. Please try again shortly, or use the phone and email links on this page.", "error" ); return; } submitButton?.setAttribute("disabled", "disabled"); showFormStatus(form, "Sending your message...", "info"); try { if (isLocalTest || submitAsJson) { const headers = { Accept: "application/json" }; if (submitAsJson) { headers["Content-Type"] = "application/json"; } const response = await fetch(endpoint, { method: "POST", headers, body: submitAsJson ? buildJsonPayload(form) : new FormData(form) }); if (submitAsJson) { await assertSuccessfulJsonResponse(response); } else if (!response.ok) { throw new Error(`Form request failed with status ${response.status}`); } } else { await fetch(endpoint, { method: "POST", mode: "no-cors", body: new FormData(form) }); } const successUrl = form.dataset.successUrl || window.RCC_CONFIG?.formSuccessUrl || "thank-you"; storeLeadSuccessPayload(form); window.location.assign(successUrl); } catch { showFormStatus( form, "We could not send the form directly. Please try again shortly, or use the phone and email links on this page.", "error" ); } finally { submitButton?.removeAttribute("disabled"); } } document.addEventListener("DOMContentLoaded", () => { rememberAttribution(); document.querySelectorAll("[data-rcc-form], form[action^='/forms/']").forEach((form) => { if (new URLSearchParams(window.location.search).get("form-error") === "1") { showFormStatus( form, "We could not send the form directly. Please use the phone or email options below if needed.", "error" ); } form.addEventListener("submit", handleFormSubmit); }); });
